   if(p.tptQuotity||p.tptMonths)r.documents[0].text='Proposition saisie : '+(p.tptQuotity?p.tptQuotity+' % de travail':'quotité à préciser')+(p.tptMonths?' pendant '+p.tptMonths+' mois':' ; durée à préciser')+'. '+r.documents[0].text;
