 function show(view){if(!['patient','rights','actions','reference'].includes(view))return;current=view;$$('[data-panel]').forEach(el=>el.hidden=el.dataset.panel!==view);$$('.nav-link').forEach(el=>{if(el.dataset.view===view)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});window.scrollTo({top:0,behavior:'instant'});const main=$('#main');main.setAttribute('tabindex','-1');main.focus({preventScroll:true});}
 function notice(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
 function summary(){
  const names={guide:result.guidance?.title||'À préciser',ordinary:'Sans origine professionnelle retenue',sudden:'Événement précis au travail',progressive:'Exposition professionnelle progressive',mixed:'Exposition + événement aigu',commute:'Accident de trajet'};
  const lines=['MESOUTILSPsy — Synthèse d’orientation','Situation au '+ATMP.date(state.asOf),result.title,'Contexte : '+names[state.origin],state.start?'Début : '+ATMP.date(state.start):'Début non renseigné','Références vérifiées le 08/11/2026. Décisions du payeur à confirmer.','',result.orientation,''];
  for(const a of result.alerts)lines.push('ATTENTION — '+a.title+' : '+a.text);
  if(questionsNow().length)lines.push('','À PRÉCISER EN CONSULTATION',...questionsNow().map(q=>'• '+q.label));
  for(const m of result.metrics)lines.push(m.label+' : '+m.value+' — '+m.detail);
  const section=(title,arr)=>{if(arr.length){lines.push('',title);for(const x of arr)lines.push((x.who?x.who+' — ':'')+x.title+' : '+x.text);}};
  if(result.prescription){lines.push('', 'PRESCRIPTION AU '+ATMP.date(result.prescription.date),result.prescription.limitLabel,result.prescription.insuranceLimitLabel?'Avis CPAM : '+result.prescription.insuranceLimitLabel:'',result.prescription.limitText);section('DOCUMENTS AUJOURD’HUI',result.prescription.documents);section('MODALITÉS DE PRESCRIPTION',result.prescription.checks);section('POINTS DE PRESCRIPTION',result.prescription.alerts);}section('INDEMNISATION',result.money);section('ACTIONS',result.actions);section('DOCUMENTS',result.forms);section('SUITES POSSIBLES',result.next);
  if(result.timeline.length)lines.push('','ÉCHÉANCES',...result.timeline.map(t=>ATMP.date(t.date)+' — '+t.title+' : '+t.text));
  if(result.missing.length)lines.push('','À VÉRIFIER',...result.missing.map(t=>'• '+t));
  lines.push('','SOURCES',...result.sources.map(id=>ATMP_SOURCES[id]).filter(Boolean).map(s=>s[0]+' — '+s[2]));
  return lines.join('\n');
 }
 async function copy(text){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.top='-9999px';document.body.appendChild(ta);ta.select();const success=document.execCommand('copy');ta.remove();if(!success)throw new Error();}notice('Copié dans le presse-papiers.');}catch{notice('Copie indisponible dans ce navigateur. Utilisez la version imprimable.');}}
 function preparePrint(){if(!state.status||result.errors.length){$('#print-sheet').innerHTML='<p>Aucune situation valide à imprimer.</p>';return;}const blocks=(title,arr)=>`<h2>${title}</h2>${arr.map(x=>`<div class="print-block"><h3>${esc(x.who?x.who+' · ':'')}${esc(x.title)}</h3><p>${esc(x.text)}</p></div>`).join('')}`;$('#print-sheet').innerHTML=`<h1>Arrêts</h1><p><b>${esc(result.title)}</b> · Situation au ${ATMP.date(state.asOf)}</p><p>${esc(result.orientation)}</p>${result.prescription?`<h2>Prescription aujourd’hui</h2><p><b>${esc(result.prescription.limitLabel)}</b>${result.prescription.insuranceLimitLabel?" / Avis CPAM : "+esc(result.prescription.insuranceLimitLabel):""} — ${esc(result.prescription.limitText)}</p>${blocks("Documents à remplir",result.prescription.documents)}${alerts(result.prescription)}${blocks("Modalités de prescription",result.prescription.checks)}`:""}${alerts(result)}${metrics(result)}${blocks('Indemnisation & maintien',result.money)}${blocks('Démarches à engager',result.actions)}${blocks('Documents',result.forms)}${blocks('Suites possibles',result.next)}<h2>Échéances</h2>${result.timeline.map(t=>`<p><b>${ATMP.date(t.date)} · ${esc(t.title)}</b><br>${esc(t.text)}</p>`).join('')}<h2>À vérifier</h2>${missing(result)}<h2>Références</h2>${result.sources.map(id=>ATMP_SOURCES[id]).filter(Boolean).map(s=>`<p><a href="${esc(s[2])}">${esc(s[1]+' · '+s[0])}</a></p>`).join('')}<p class="footnote">Mesoutilspsy · version 1.2 · Références vérifiées le 08/11/2026. Aide à l’orientation ; ne vaut ni décision, ni certificat, ni attestation de droits.</p>`;}
