 const examples={tpt:{status:'titular',branch:'FPE',stop:'tpt',rxStage:'initial',origin:'ordinary',capacity:'partial',tptQuotity:'60',tptMonths:'6',tptAfter:'long',asOf:'2026-11-08'},private:{status:'private',origin:'ordinary',seniority:'48',stop:'active',start:'2026-07-08',asOf:'2026-11-08',capacity:'unable',ald:'nonexempt',aldLink:'yes',aldTransition:'unknown',aldFirst:'2026-07-08',carence:'extension',salary:'2400',rights:'yes',employerEligible:'yes',employerUsed:'60'},public:{status:'titular',origin:'ordinary',branch:'FPE',leave:'clm',stop:'active',start:'2025-06-01',capacity:'unable',careLong:'yes',treatment:'2800',asOf:'2026-11-08'},at:{status:'private',stop:'planned',origin:'guide',workContext:'work',onset:'sudden',eventDated:'yes',lesion:'yes',workLink:'yes',capacity:'unable',asOf:'2026-11-08'}};
 form.addEventListener('input',e=>{readForm();if(e.target.name==='rxDays'){state.rxJustified=false;form.elements.namedItem('rxJustified').checked=false;}render();});
 form.addEventListener('change',e=>{readForm();if(e.target.name==='status'){state.rxJustified=false;state.leave='unknown';state.treatment='';state.officialIj='';state.leaveHistory='unknown';state.tptQuotity='';state.tptUsed='';}if(e.target.name==='stop'){state.rxStage='auto';state.rxDays='';state.rxJustified=false;}if(e.target.name==='rxStage')state.rxJustified=false;if(e.target.name==='origin'||(e.target.name==='stop'&&state.stop==='planned')){state.rxJustified=false;state.recognized='no';state.stage='acute';state.relapseRecognized='pending';state.mpDateConfirmed=false;state.eventDate='';}if(e.target.name==='ald'){state.aldLink='unknown';state.aldTransition='unknown';state.aldFirst='';state.firstAldCarence='unknown';}syncForm();render();});
 form.addEventListener('submit',e=>{e.preventDefault();readForm();render();if(!state.status){$('#status').focus();notice('Choisir le statut professionnel.');return;}if(result.errors.length){$('#form-errors').scrollIntoView({block:'center'});return;}show(e.submitter?.textContent.includes('Actualiser')?'rights':'actions');});
 document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view)show(view.dataset.view);const ex=e.target.closest('[data-example]');if(ex){state={...ATMP.EMPTY,...examples[ex.dataset.example]};syncForm();render();notice('Exemple fictif chargé. Tous les paramètres sont modifiables.');}if(e.target.closest('[data-copy]'))copy(summary());if(e.target.closest('[data-print]'))print();if(e.target.closest('[data-certificate-copy]'))copy($('#certificate-template').value);});
